"""
ワーシャルフロイド法 (Floyd-Warshall: 全点対最短経路 / APSP)
Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)

【概要・用途】
すべての頂点ペア (i, j) 間の最短距離を O(V^3) で求める。
負の重みの辺があっても動作し、負閉路の検出も可能 (自己ループ d[i][i] < 0 となれば負閉路存在)。
頂点数 V <= 400 程度まで適用可能。

【引数・戻り値】
- warshall_floyd(n, dist, inf=10**18):
  - n: 頂点数 (0-indexed: 0 ~ n-1)
  - dist: n x n の隣接行列 (初期状態: d[i][i]=0, 辺(u,v,w)は d[u][v]=w, その他 INF)
  - 戻り値: (dist, has_neg_cycle)
"""

# https://github.com/ddfkit/acsampl/blob/main/w_f.py
# Generated by Gemini prior to contest (AtCoder Rule 20251003 compliant)
def warshall_floyd(n,d,inf=10**18):
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if d[i][k]<inf and d[k][j]<inf:
                    d[i][j]=min(d[i][j],d[i][k]+d[k][j])
    neg=any(d[i][i]<0 for i in range(n))
    return d,neg

if __name__ == "__main__":
    INF = 10**18
    # 頂点4, 辺: (0->1: 1), (1->2: 2), (0->2: 5), (2->3: 1)
    d = [[0 if i == j else INF for j in range(4)] for i in range(4)]
    edges = [(0, 1, 1), (1, 2, 2), (0, 2, 5), (2, 3, 1)]
    for u, v, w in edges: d[u][v] = w
    res, neg = warshall_floyd(4, d)
    assert not neg
    assert res[0][2] == 3  # 0 -> 1 -> 2
    assert res[0][3] == 4  # 0 -> 1 -> 2 -> 3
    print("w_f.py: tests passed!")
